-- =====================================================================================
-- Conversation.ParentBranchID — Fork-Scoped Side Questions
--
-- Extends MJ: Conversations (`${flyway:defaultSchema}.Conversation`) with an optional
-- `ParentBranchID` FK pointing to `${flyway:defaultSchema}.ConversationBranch(ID)` so
-- a persistent side-question thread (`ParentID` + `TypeID = SIDE_QUESTION`) can scope
-- cleanly to either the parent conversation's Main trunk (`ParentBranchID IS NULL`) or
-- a specific fork branch (`ParentBranchID = <branchId>`).
--
-- Builds on `V202611221635__v6.3.x__Conversation_ParentID.sql`, which already added
-- `ParentID`, `FK_Conversation_Parent`, and `IX_Conversation_ParentID`.
--
-- `FK_Conversation_ParentBranchID` intentionally omits ON DELETE CASCADE to avoid
-- SQL Server multiple-cascade-path errors (`Conversation` -> `ConversationBranch` ->
-- `Conversation`). Application-layer delete logic in `MJConversationBranchEntityServer`
-- cleans up fork-scoped side-question threads before `spDeleteConversationBranch`.
-- =====================================================================================

ALTER TABLE [${flyway:defaultSchema}].[Conversation]
    ADD [ParentBranchID] UNIQUEIDENTIFIER NULL;
GO

ALTER TABLE [${flyway:defaultSchema}].[Conversation]
    ADD CONSTRAINT [FK_Conversation_ParentBranchID]
    FOREIGN KEY ([ParentBranchID]) REFERENCES [${flyway:defaultSchema}].[ConversationBranch]([ID]);
GO

ALTER TABLE [${flyway:defaultSchema}].[Conversation]
    ADD CONSTRAINT [CK_Conversation_ParentLink]
    CHECK (
        ([ParentBranchID] IS NULL OR [ParentID] IS NOT NULL)
        AND ([ParentID] IS NULL OR [ParentID] <> [ID])
    );
GO

CREATE NONCLUSTERED INDEX [IX_Conversation_ParentBranchID]
    ON [${flyway:defaultSchema}].[Conversation] ([ParentBranchID])
    WHERE [ParentBranchID] IS NOT NULL;
GO

EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Optional ConversationBranch ID on the parent conversation identifying which fork path a child side-question thread is scoped to. NULL means the parent conversation''s Main trunk.',
    @level0type = N'SCHEMA', @level0name = N'${flyway:defaultSchema}',
    @level1type = N'TABLE',  @level1name = N'Conversation',
    @level2type = N'COLUMN', @level2name = N'ParentBranchID';
GO























































