      SELECT 1 FROM [${flyway:defaultSchema}].[GeneratedCode] WHERE [CategoryID] = (SELECT [ID] FROM [${flyway:defaultSchema}].[vwGeneratedCodeCategories] WHERE [Name]='CodeGen: Validators') AND [LinkedEntityID] = 'E0238F34-2837-EF11-86D4-6045BDEE16E6' AND [LinkedRecordPrimaryKey] = '13248F34-2837-EF11-86D4-6045BDEE16E6' AND [Name] = 'ValidateParentAndParentBranchHierarchy'
   )
   BEGIN
      INSERT INTO [${flyway:defaultSchema}].[GeneratedCode] ([ID], [CategoryID], [GeneratedByModelID], [GeneratedAt], [Language], [Status], [Source], [Code], [Description], [Name], [LinkedEntityID], [LinkedRecordPrimaryKey])
VALUES ('413bf8c5-76f3-42fa-8294-ba4f62034f22', (SELECT [ID] FROM [${flyway:defaultSchema}].[vwGeneratedCodeCategories] WHERE [Name]='CodeGen: Validators'), '4B500A24-0259-4EFF-9E34-24E9F5EC9DAB', GETUTCDATE(), 'TypeScript', 'Approved', '(([ParentBranchID] IS NULL OR [ParentID] IS NOT NULL) AND ([ParentID] IS NULL OR [ParentID]<>[ID]))', 'public ValidateParentAndParentBranchHierarchy(result: ValidationResult): void {
	if (this.ParentBranchID != null && this.ParentID == null) {
		result.Errors.push(new ValidationErrorInfo(
			"ParentID",
			"A parent must be specified when a parent branch is set.",
			this.ParentID,
			ValidationErrorType.Failure
		));
	}

	if (this.ParentID != null && this.ID != null && UUIDsEqual(this.ParentID, this.ID)) {
		result.Errors.push(new ValidationErrorInfo(
			"ParentID",
			"A record cannot be its own parent.",
			this.ParentID,
			ValidationErrorType.Failure
		));
	}
}', 'A record cannot be its own parent, and specifying a parent branch requires a parent record to be set.', 'ValidateParentAndParentBranchHierarchy', 'E0238F34-2837-EF11-86D4-6045BDEE16E6', '13248F34-2837-EF11-86D4-6045BDEE16E6')
   END;

